import assert from 'node:assert/strict';
import {entries,crossings,ContactTimeline,chooseIndex} from './contact-core.mjs';
let count=0;const test=(name,fn)=>{fn();count++;console.log('PASS',name);};
const profile={frames:61,contacts:{'foot.l':{planted:[[1,10],[41,61]]},'foot.r':{planted:[[11,30]]}}};
test('wrapped stance yields one entry per foot',()=>assert.equal(entries(profile).length,2));
test('wrapped start is not duplicate',()=>assert.ok(!entries(profile).some(x=>x.phase===0)));
test('all cycle entries, not firstPlant',()=>assert.deepEqual(crossings(entries(profile),0,1).map(x=>x.foot),['r','l']));
test('loop boundary crosses exactly once',()=>assert.equal(crossings([{phase:0,foot:'l'}],.9,1.1).length,1));
test('background backlog dropped',()=>assert.equal(crossings(entries(profile),0,4).length,0));
test('stationary emits no step',()=>{const t=new ContactTimeline();assert.equal(t.advance({owner:'w',phase:1,duration:1,time:1,points:entries(profile),moving:false,surfaceAt:()=> 'grass'}).length,0);});
test('airborne emits no step',()=>{const t=new ContactTimeline();t.support(false,0,'grass');t.advance({owner:'w',phase:0,duration:1,time:0,points:entries(profile),moving:true});assert.equal(t.advance({owner:'w',phase:1,duration:1,time:1,points:entries(profile),moving:true}).length,0);});
test('landing only on support edge',()=>{const t=new ContactTimeline();assert.equal(t.support(true,0,'grass'),null);t.support(false,1,'grass');assert.equal(t.support(true,2,'grass').kind,'land');assert.equal(t.support(true,3,'grass'),null);});
test('blend owner change does not catch up',()=>{const t=new ContactTimeline();t.advance({owner:'w',phase:0,moving:true});assert.equal(t.advance({owner:'r',phase:.8,moving:true}).length,0);});
test('dedupe same foot under 120ms',()=>{const t=new ContactTimeline();t.accept({foot:'l',kind:'footstep',time:1});assert.equal(t.accept({foot:'l',kind:'footstep',time:1.01}),null);});
test('per-foot surface resolver',()=>{const t=new ContactTimeline();t.advance({owner:'w',phase:0,moving:true});const out=t.advance({owner:'w',phase:1,duration:1,time:1,points:entries(profile),moving:true,surfaceAt:f=>f==='l'?'grass':'gravel'});assert.deepEqual(out.map(c=>c.surface),['gravel','grass']);});
test('repeat-free bank selection',()=>{for(let last=0;last<5;last++)for(let k=0;k<100;k++)assert.notEqual(chooseIndex(5,last,()=>k/100),last);});
test('one timeline additive cue packet',()=>{const p=new ContactTimeline().packet();assert.equal(p.schema,'kfb.performance/1');assert.deepEqual([p.sfx,p.vfx,p.lights],[[],[],[]]);});
test('landing suppresses overlapping planted step',()=>{const t=new ContactTimeline();t.advance({owner:'w',phase:0,moving:true});t.support(false,0,'grass');t.support(true,.1,'grass');assert.equal(t.advance({owner:'w',phase:.2,time:.2,duration:1,points:[{phase:.15,foot:'l'}],moving:true,surfaceAt:()=> 'grass'}).length,0);});
test('short grazing intervals excluded without changing raw contacts',()=>{const p={frames:65,contacts:{'foot.l':{planted:[[1,3],[13,29],[65,65]]},'foot.r':{planted:[[33,34],[45,59]]}}};assert.deepEqual(entries(p,{duration:1.0666667}).map(e=>e.phase),[.1875,.6875]);assert.equal(p.contacts['foot.l'].planted.length,3);});
test('ten minute walk phase stream has no cumulative contact drift',()=>{const duration=1.0666667222976685,points=[{foot:'l',phase:.1875},{foot:'r',phase:.6875}],t=new ContactTimeline();t.advance({owner:'w',phase:0,moving:true});for(let frame=1;frame<=36000;frame++)t.advance({owner:'w',phase:frame/60/duration,duration,time:frame/60,points,moving:true,surfaceAt:()=> 'grass'});assert.equal(t.cues.length,1125);for(let i=1;i<t.cues.length;i++)assert.ok(Math.abs(t.cues[i].time-t.cues[i-1].time-duration/2)<1e-10);});
console.log(`${count} passed; 0 failed`);
